    if (menuRoutePath && !routeMap[menuRoutePath.toLowerCase()]) {
      return fail('微服务菜单【' + text(menu.Name || menu.Id, '未命名') + '】引用路由 '
        + menuRoutePath + '，但当前 committed ApplicationBundle 未包含该路由');
