            if (timestampDefault) {
                definition += ' DEFAULT ' + timestampDefault;
            } else if (/^b'.*'$/i.test(defaultText)) {
                definition += runtimeIsSqlServer
                    ? ' DEFAULT ' + defaultText.substring(2, defaultText.length - 1)
                    : ' DEFAULT ' + defaultText;
            } else {
